<?php require_once __DIR__.'/../includes/bootstrap.php'; require_admin(); $edit=null; if(isset($_GET['edit'])){$s=db()->prepare('SELECT * FROM categories WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();} $cats=db()->query('SELECT c.*,COUNT(p.id) product_count FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.name')->fetchAll(); ?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Danh mục sản phẩm</title><link rel="stylesheet" href="../assets/css/style-admin.css"></head><body><div class="admin-container"><aside class="sidebar"><div class="brand">🛡 ADMIN PANEL</div><ul class="menu"><li><a href="index.php">📊 Dashboard</a></li><li><a href="products.php">📦 Quản lý sản phẩm</a></li><li class="active"><a href="categories.php">☷ Danh mục sản phẩm</a></li><li><a href="orders.php">🧾 Quản lý đơn hàng</a></li><li><a href="../index.php">← Về trang chủ</a></li></ul></aside><main class="main-content"><div class="top-header"><h2>Danh mục sản phẩm</h2><button class="btn-add" onclick="openModal()">＋ Thêm danh mục</button></div><div class="table-card"><div class="table-header"><h3>Danh sách danh mục</h3></div><table class="admin-table"><thead><tr><th>ID</th><th>Tên danh mục</th><th>Slug</th><th>Số sản phẩm</th><th>Hành động</th></tr></thead><tbody><?php foreach($cats as $c): ?><tr><td><?=$c['id']?></td><td><?=e($c['name'])?></td><td><?=e($c['slug'])?></td><td><?=$c['product_count']?></td><td><a class="btn-action btn-edit" href="?edit=<?=$c['id']?>">Sửa</a><form style="display:inline" method="post" action="../actions/category.php"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$c['id']?>"><button class="btn-action btn-delete" onclick="return confirm('Bạn có chắc muốn xóa danh mục này không?')">Xóa</button></form></td></tr><?php endforeach; ?></tbody></table></div></main></div><div class="modal-overlay <?= $edit?'is-open':'' ?>" id="categoryModal"><div class="modal-box"><div class="modal-header"><h3><?= $edit?'Sửa danh mục':'Thêm danh mục' ?></h3><button class="modal-close" onclick="closeModal()">×</button></div><form class="admin-form" method="post" action="../actions/category.php"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=$edit['id']??0?>"><label>Tên danh mục<input name="name" value="<?=e($edit['name']??'')?>" required></label><label>Slug<input name="slug" value="<?=e($edit['slug']??'')?>" required></label><div class="form-actions"><button type="button" class="btn-secondary" onclick="closeModal()">Hủy</button><button class="btn-add">Lưu danh mục</button></div></form></div></div><script>function openModal(){document.getElementById('categoryModal').classList.add('is-open')}function closeModal(){document.getElementById('categoryModal').classList.remove('is-open')}document.getElementById('categoryModal').addEventListener('click',function(e){if(e.target===this)closeModal()})</script></body></html>
